const kursiArabic='اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ';
const kursiMeanings=[
 'Allah — Ondan başqa ibadətə layiq məbud yoxdur. O, daim diridir, hər şeyi qoruyub idarə edəndir. Onu nə mürgü tutar, nə də yuxu. Göylərdə və yerdə nə varsa Onundur. Onun icazəsi olmadan kim Onun yanında şəfaət edə bilər? O, onların önlərində və arxalarında olanı bilir. Onlar isə Onun elmindən yalnız Onun istədiyi qədərini qavraya bilərlər. Onun kürsüsü göyləri və yeri əhatə edir. Bunları qorumaq Ona ağır gəlmir. O, ucadır, əzəmətlidir.',
 'Allah; O’ndan başka ibadete layık ilah yoktur. O daima diridir, her şeyi ayakta tutandır. O’nu ne uyuklama ne uyku tutar. Göklerde ve yerde ne varsa O’nundur. İzni olmadan O’nun katında kim şefaat edebilir? O, önlerindekini ve arkalarındakini bilir. Onlar O’nun ilminden ancak dilediği kadarını kavrar. Kürsüsü gökleri ve yeri kuşatır. Onları korumak O’na ağır gelmez. O yücedir, büyüktür.',
 'Аллах — нет божества, достойного поклонения, кроме Него. Он Вечно Живой, Поддерживающий всё сущее. Ни дремота, ни сон не овладевают Им. Ему принадлежит всё на небесах и земле. Кто заступится перед Ним без Его дозволения? Он знает, что перед ними и что позади них. Они постигают из Его знания лишь то, что Он пожелает. Его Престол охватывает небеса и землю, и их сохранение не обременяет Его. Он Возвышенный, Великий.',
 'Allah: none is worthy of worship except Him, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep touches Him. Everything in the heavens and earth belongs to Him. Who can intercede before Him without His permission? He knows what lies before and behind them. They comprehend only what He wills of His knowledge. His Kursi encompasses the heavens and earth; preserving them does not burden Him. He is the Most High, the Magnificent.',
 'الله وحده المستحق للعبادة، الحي الدائم، القائم بتدبير كل شيء. لا يصيبه نعاس ولا نوم. كل ما في السماوات والأرض ملكه، ولا يشفع أحد عنده إلا بإذنه. يعلم ما أمام الخلق وما خلفهم، ولا يدركون من علمه إلا ما أراد. وسع كرسيه السماوات والأرض، ولا يثقله حفظهما، وهو العلي العظيم.'
];
function devotionDuas(){const i=exIndex();return [
 {id:14,title:ex('ayat'),allTitles:[...experienceCopy.ayat,'Ayətəl kürsi','Ayatel kursi','Ayatul kursi','Ayet el kursi','Бакара','Bəqərə 255'],subtitle:'Quran 2:255',arabic:kursiArabic,translit:'Allahu lə ilahə illə huvəl-həyyul-qayyum. Lə təxuzuhu sinətun və lə nəvm. Ləhu mə fis-səməvati və mə fil-ərd. Mən zəlləzi yəşfəu indəhu illə bi-iznih. Yələmu mə bəynə əydihim və mə xalfəhum. Və lə yuhitunə bişəyin min ilmihi illə bimə şəə. Vəsia kursiyyuhus-səməvati vəl-ərd. Və lə yəuduhu hifzuhumə. Və huvəl-aliyyul-azim.',meaning:kursiMeanings[i],source:'Quran 2:255',sourceUrl:'https://quran.com/2/255'},
 {id:15,title:ex('foodAfter'),allTitles:[...experienceCopy.foodAfter,'Yemək duası','Yemek duası','Meal food prayer','الطعام'],subtitle:ex('foodAfter'),arabic:'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ',translit:'Əlhəmdu lilləhilləzi ətaməni həzə və razəqanihi min ğayri həvlin minni və lə quvvəh.',meaning:['Bunu mənə yedirdən və mənim bir gücüm, qüvvətim olmadan mənə ruzi verən Allaha həmd olsun.','Bana bunu yediren ve benim bir güç ve kuvvetim olmadan rızık olarak veren Allah’a hamdolsun.','Хвала Аллаху, Который накормил меня этим и даровал это без моей силы и могущества.','Praise be to Allah, who fed me this and provided it without any strength or power of my own.','الحمد لله الذي أطعمني هذا الطعام ورزقنيه دون قوة أو قدرة مني.'][i],source:'Tirmidhi 3458',sourceUrl:'https://sunnah.com/tirmidhi:3458'},
 {id:16,title:ex('foodForgot'),allTitles:[...experienceCopy.foodForgot,'Yemək duası','Yemek duası','Food Bismillah'],subtitle:ex('foodBefore'),arabic:'بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ',translit:'Bismilləhi fi əvvəlihi və axirih.',meaning:['Əvvəlində də, sonunda da Allahın adı ilə.','Başında da sonunda da Allah’ın adıyla.','С именем Аллаха в начале и в конце.','In the name of Allah, at its beginning and its end.','باسم الله في بداية الطعام ونهايته.'][i],source:'Tirmidhi 1858',sourceUrl:'https://sunnah.com/tirmidhi:1858'}
 ];}
function duaSource(d){const link=d.sourceUrl||(d.source?.startsWith('Quran ')?'https://quran.com/'+d.source.slice(6).replace(':','/').split('–')[0]:'');return d.source?`<p class="notice center dua-source">${link?`<a href="${esc(link)}" target="_blank" rel="noopener">${ex('source')}: ${esc(d.source)} ↗</a>`:esc(d.source)}</p>`:''}
